import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { validateCapabilityMatrix } from "../src/capability.ts";

const here = dirname(fileURLToPath(import.meta.url));
const matrixPath = resolve(here, "../../../specs/adapter-capabilities.v0.json");
const capabilityPath = resolve(here, "../src/capability.ts");
const frozen = () => JSON.parse(readFileSync(matrixPath, "utf8"));

test("invalid capability-validation outcomes expose errors without derived values", () => {
  const malformedCases = [
    [
      "row",
      (matrix: any) => { matrix.rows[2] = "user instruction"; },
      "ROW_NOT_AN_OBJECT"
    ],
    [
      "runtime cell",
      (matrix: any) => { matrix.rows[3].runtimes.codex = "app-server"; },
      "CELL_NOT_AN_OBJECT tool_call codex"
    ]
  ] as const;

  for (const [label, corrupt, expectedError] of malformedCases) {
    const matrix = frozen();
    corrupt(matrix);
    const result = validateCapabilityMatrix(matrix);

    assert.equal(result.ok, false, `${label} corruption was accepted`);
    if (result.ok) assert.fail(`${label} corruption unexpectedly produced a valid result`);
    assert.ok(
      result.errors.some((error) => error.startsWith(expectedError)),
      `${label} corruption produced ${result.errors.join("; ") || "no error"}`
    );
    assert.equal("coverage" in result, false, `${label} failure exposed derived coverage`);
    assert.equal(
      "required_event_groups" in result,
      false,
      `${label} failure exposed derived required-event groups`
    );
  }
});

test("capability-validation types expose trusted values only after success", () => {
  const tempDir = mkdtempSync(join(tmpdir(), "capability-validation-result-"));
  const probePath = join(tempDir, "result-contract.ts");
  const relativeCapabilityPath = relative(tempDir, capabilityPath).replaceAll("\\", "/");
  const capabilityImport = relativeCapabilityPath.startsWith(".")
    ? relativeCapabilityPath
    : `./${relativeCapabilityPath}`;

  writeFileSync(probePath, `
import { validateCapabilityMatrix } from ${JSON.stringify(capabilityImport)};
import type { CapabilityRow } from ${JSON.stringify(capabilityImport)};

const valid = validateCapabilityMatrix({});
if (valid.ok) {
  const rows: CapabilityRow[] = valid.rows;
  const coverage = valid.coverage;
  void rows;
  void coverage;
}

const malformedRow = validateCapabilityMatrix({ rows: ["not an object"] });
if (!malformedRow.ok) {
  const errors: string[] = malformedRow.errors;
  void errors;
  // @ts-expect-error Invalid input must not be exposed as validated capability rows.
  const unsafeRows: CapabilityRow[] = malformedRow.rows;
  // @ts-expect-error Derived coverage exists only for successful validation.
  const unsafeCoverage = malformedRow.coverage;
}

const malformedCell = validateCapabilityMatrix({
  rows: [{ event_group: "tool_call", runtimes: { codex: "not a cell" } }]
});
if (!malformedCell.ok) {
  // @ts-expect-error A malformed-cell result must not expose validated rows.
  const unsafeRows: CapabilityRow[] = malformedCell.rows;
  // @ts-expect-error A malformed-cell result must not expose derived coverage.
  const unsafeCoverage = malformedCell.coverage;
}
`, "utf8");

  try {
    const compilation = spawnSync(
      "tsc",
      [
        "--noEmit",
        "--strict",
        "--target", "ES2023",
        "--module", "ESNext",
        "--moduleResolution", "Bundler",
        "--allowImportingTsExtensions",
        "--skipLibCheck",
        probePath
      ],
      { encoding: "utf8" }
    );

    assert.ifError(compilation.error);
    assert.equal(
      compilation.status,
      0,
      [compilation.stdout, compilation.stderr].filter(Boolean).join("\n")
    );
  } finally {
    rmSync(tempDir, { recursive: true, force: true });
  }
});
